          "get": {
            "summary": "Fetch alert state",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/feeds/{feed_id}/live/digest": {
          "get": {
            "summary": "Live feed digest (verify alert landed)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        }
      }
    }
  },
